CREATE TABLE billing_balance_publications (
 id TEXT PRIMARY KEY NOT NULL, loan_id TEXT NOT NULL REFERENCES loans(id), member_id TEXT NOT NULL REFERENCES members(id),
 link_id TEXT NOT NULL REFERENCES member_user_links(id), user_id TEXT NOT NULL REFERENCES "user"(id),
 member_name TEXT NOT NULL, member_number TEXT NOT NULL, user_name TEXT NOT NULL, user_email TEXT NOT NULL,
 currency TEXT NOT NULL, as_of_date TEXT NOT NULL, principal_minor TEXT NOT NULL, interest_minor TEXT NOT NULL,
 billing_revision INTEGER NOT NULL, published_by TEXT NOT NULL REFERENCES "user"(id), request_key TEXT NOT NULL UNIQUE,
 published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, withdrawn_at TEXT, withdrawn_by TEXT REFERENCES "user"(id), withdraw_key TEXT UNIQUE,
 CHECK((withdrawn_at IS NULL AND withdrawn_by IS NULL AND withdraw_key IS NULL) OR (withdrawn_at IS NOT NULL AND withdrawn_by IS NOT NULL AND withdraw_key IS NOT NULL))
);
CREATE TRIGGER billing_balance_publish_guard BEFORE INSERT ON billing_balance_publications BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.published_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_billing_revisions r JOIN loan_billing_configs c ON c.loan_id=r.loan_id JOIN loans l ON l.id=r.loan_id JOIN members m ON m.id=l.member_id AND m.status='active' JOIN member_user_links k ON k.member_id=m.id AND k.revoked_at IS NULL JOIN "user" u ON u.id=k.user_id WHERE r.loan_id=NEW.loan_id AND r.revision=NEW.billing_revision AND l.member_id=NEW.member_id AND l.currency=NEW.currency AND k.id=NEW.link_id AND k.user_id=NEW.user_id AND m.full_name=NEW.member_name AND m.member_number=NEW.member_number AND u.name=NEW.user_name AND u.email=NEW.user_email AND NOT EXISTS(SELECT 1 FROM loan_source_voids x WHERE x.source_kind='loan' AND x.source_id=l.id)) THEN RAISE(ABORT,'billing review or recipient changed') END;
 SELECT CASE WHEN date(NEW.as_of_date,'+0 days') IS NOT NEW.as_of_date OR NEW.as_of_date>date('now','+3 hours') OR length(NEW.principal_minor) NOT BETWEEN 1 AND 30 OR NEW.principal_minor GLOB '*[^0-9]*' OR (length(NEW.principal_minor)>1 AND substr(NEW.principal_minor,1,1)='0') OR length(NEW.interest_minor) NOT BETWEEN 1 AND 30 OR NEW.interest_minor GLOB '*[^0-9]*' OR (length(NEW.interest_minor)>1 AND substr(NEW.interest_minor,1,1)='0') THEN RAISE(ABORT,'invalid billing snapshot') END;
END;
CREATE TRIGGER billing_balance_immutable BEFORE UPDATE ON billing_balance_publications WHEN NEW.id IS NOT OLD.id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.member_id IS NOT OLD.member_id OR NEW.link_id IS NOT OLD.link_id OR NEW.user_id IS NOT OLD.user_id OR NEW.member_name IS NOT OLD.member_name OR NEW.member_number IS NOT OLD.member_number OR NEW.user_name IS NOT OLD.user_name OR NEW.user_email IS NOT OLD.user_email OR NEW.currency IS NOT OLD.currency OR NEW.as_of_date IS NOT OLD.as_of_date OR NEW.principal_minor IS NOT OLD.principal_minor OR NEW.interest_minor IS NOT OLD.interest_minor OR NEW.billing_revision IS NOT OLD.billing_revision OR NEW.published_by IS NOT OLD.published_by OR NEW.request_key IS NOT OLD.request_key OR NEW.published_at IS NOT OLD.published_at OR OLD.withdrawn_at IS NOT NULL OR NEW.withdrawn_at IS NULL OR NEW.withdrawn_by IS NULL OR NEW.withdraw_key IS NULL OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.withdrawn_by AND role='admin') BEGIN SELECT RAISE(ABORT,'billing publication immutable'); END;
CREATE TRIGGER billing_balance_no_delete BEFORE DELETE ON billing_balance_publications BEGIN SELECT RAISE(ABORT,'billing publication immutable'); END;
